const money = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL", maximumFractionDigits: 0 }), date = tenantDateTimeFormatter({ dateStyle: "short" }), dateTime = tenantDateTimeFormatter({ dateStyle: "short", timeStyle: "short" });
const labels: Record<string, string> = { active: "Ativo", inactive: "Inativo", goods: "Mercadorias", services: "Serviços", logistics: "Logística", technology: "Tecnologia", utilities: "Utilidades", other: "Outros", pending: "Pendente", approved: "Homologado", conditional: "Condicional", rejected: "Reprovado", expired: "Vencido", unrated: "Não avaliado", low: "Baixo", medium: "Médio", high: "Alto", blocked: "Bloqueado", valid: "Válido", tax: "Fiscal", license: "Licença", certificate: "Certificado", insurance: "Seguro", contract: "Contrato", bank: "Bancário", note: "Nota", call: "Ligação", email: "E-mail", meeting: "Reunião", task: "Tarefa", negotiation: "Negociação", not_informed: "Não informado", mei: "MEI", simples: "Simples Nacional", presumed: "Lucro presumido", actual: "Lucro real", individual: "Pessoa física", draft: "Rascunho", ordered: "Pedido emitido", partially_received: "Recebido parcialmente", received: "Recebido", cancelled: "Cancelado", open: "Aberto", partial: "Parcial", paid: "Pago", manual: "Manual", purchase: "Compras", invoice: "Nota fiscal", import: "Importação", referral: "Indicação" };

