type Supplier = { id: number; version: number; type: string; name: string; tradeName?: string | null; document: string; email?: string | null; phone?: string | null; status: string; category: string; origin: string; buyer?: string | null; riskRating: string; homologationStatus: string; taxRegime: string; stateRegistration?: string | null; municipalRegistration?: string | null; website?: string | null; paymentTerms?: string | null; paymentTermsDays: number; deliveryLeadTimeDays: number; minimumOrder: number; notes?: string | null; updatedAt: string; addresses: Array<Record<string, unknown> & { id?: number; label?: string; city?: string | null; state?: string | null; primary?: boolean }>; contacts: Array<{ id: number; name: string; role?: string | null; email?: string | null; phone?: string | null; primary: boolean }>; tagLinks: Array<{ tag: { id: number; name: string; color: string } }>; interactions: Array<{ id: number; type: string; subject: string; notes?: string | null; dueAt?: string | null; completedAt?: string | null; createdBy: string; createdAt: string }>; complianceDocuments: Array<{ id: number; type: string; name: string; number?: string | null; status: string; issuedAt?: string | null; expiresAt?: string | null; fileReference?: string | null; notes?: string | null }>; evaluations: Array<{ id: number; qualityScore: number; deliveryScore: number; commercialScore: number; complianceScore: number; notes?: string | null; evaluatedBy: string; evaluatedAt: string }>; metrics: Metrics; health: { score: number; issues: string[] }; _count: { products: number; purchaseOrders: number; purchaseInvoices: number; financialTitles: number } };
type DetailSupplier = Supplier & { products: Array<{ productId: number; supplierCode?: string | null; lastCost?: number | null; leadTimeDays?: number | null; minimumOrder?: number | null; preferred: boolean; product: { id: number; name: string; sku: string; unit: string; cost: number; stock: number; active: boolean } }>; purchaseOrders: Array<{ id: number; number: string; status: string; expectedAt?: string | null; dueAt?: string | null; total: number; createdAt: string; _count: { items: number; receipts: number } }>; quotationOffers: Array<{ id: number; total: number; leadTimeDays: number; paymentTerms?: string | null; selected: boolean; createdAt: string; quotation: { id: number; number: string; title: string; status: string } }>; financialTitles: Array<{ id: number; description: string; documentNumber?: string | null; status: string; amount: number; paidAmount: number; dueAt: string }>; purchaseInvoices: Array<{ id: number; number: string; series: string; status: string; issueDate: string; total: number; receivedAt?: string | null }> };
type Data = { items: Supplier[]; tags: Array<{ id: number; name: string; color: string }>; duplicates: Array<{ field: string; value: string; items: Array<{ id: number; name: string }> }>; generatedAt: string; capabilities: { canWrite: boolean }; pagination: { page: number; limit: number; total: number; pages: number }; summary: { total: number; active: number; approved: number; new30d: number; spend: number; openPayables: number; overduePayables: number; averagePerformance: number; linkedProducts: number }; analytics: { categories: Array<{ category: string; _count: { _all: number } }>; risks: Array<{ riskRating: string; _count: { _all: number } }>; homologations: Array<{ homologationStatus: string; _count: { _all: number } }>; growth: Array<{ month: string; count: number }>; quality: { missingEmail: number; missingPhone: number; missingAddress: number; pendingDocuments: number; duplicateGroups: number }; topSuppliers: Array<{ id: number; name: string; spend: number }> } };
const emptyData: Data = { items: [], tags: [], duplicates: [], generatedAt: "", capabilities: { canWrite: false }, pagination: { page: 1, limit: 25, total: 0, pages: 1 }, summary: { total: 0, active: 0, approved: 0, new30d: 0, spend: 0, openPayables: 0, overduePayables: 0, averagePerformance: 0, linkedProducts: 0 }, analytics: { categories: [], risks: [], homologations: [], growth: [], quality: { missingEmail: 0, missingPhone: 0, missingAddress: 0, pendingDocuments: 0, duplicateGroups: 0 }, topSuppliers: [] } };

export function SupplierCenter() {
  const [data, setData] = useState<Data>(emptyData), [loading, setLoading] = useState(true), [fatal, setFatal] = useState(""), [message, setMessage] = useState(""), [error, setError] = useState(""), [view, setView] = useState<"overview" | "portfolio" | "quality">("overview"), [filters, setFilters] = useState({ search: "", status: "", category: "", risk: "", homologation: "", attention: "", sort: "name" }), [page, setPage] = useState(1), [selected, setSelected] = useState<number[]>([]), [busy, setBusy] = useState(false), [profile, setProfile] = useState<Supplier | null | undefined>(undefined), [detail, setDetail] = useState<DetailSupplier | null>(null), [detailMeta, setDetailMeta] = useState<{ productCatalog: Array<{ id: number; name: string; sku: string; unit: string; cost: number }>; audit: Array<{ id: string; action: string; createdAt: string }> }>({ productCatalog: [], audit: [] }), [detailLoading, setDetailLoading] = useState(false), [importOpen, setImportOpen] = useState(false);
  const params = useMemo(() => { const value = new URLSearchParams({ page: String(page), limit: "25", sort: filters.sort }); Object.entries(filters).forEach(([key, item]) => { if (key !== "sort" && item) value.set(key, item); }); return value; }, [filters, page]);
  async function load() { setError(""); try { const response = await fetch(`/api/erp/suppliers?${params}`, { cache: "no-store" }), body = await response.json(); if (!response.ok) throw new Error(body.error || "Não foi possível carregar os fornecedores."); setData(body); setSelected((current) => current.filter((id) => body.items.some((item: Supplier) => item.id === id))); setFatal(""); } catch (reason) { const text = reason instanceof Error ? reason.message : "Falha ao carregar fornecedores."; if (!data.generatedAt) setFatal(text); else setError(text); } finally { setLoading(false); } }
  useEffect(() => { void load(); }, [params]);
  async function openDetail(id: number) { setDetailLoading(true); setDetail(null); try { const response = await fetch(`/api/erp/suppliers/${id}`, { cache: "no-store" }), body = await response.json(); if (!response.ok) throw new Error(body.error || "Não foi possível abrir o fornecedor."); setDetail(body.supplier); setDetailMeta({ productCatalog: body.productCatalog, audit: body.audit }); } catch (reason) { setError(reason instanceof Error ? reason.message : "Não foi possível abrir o fornecedor."); } finally { setDetailLoading(false); } }
  async function command(payload: Record<string, unknown>, success: string, id?: number) { setBusy(true); setError(""); try { const response = await fetch(id ? `/api/erp/suppliers/${id}` : "/api/erp/suppliers", { method: id ? "PATCH" : "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(payload) }), body = await response.json(); if (!response.ok) throw new Error(body.error || "Operação não concluída."); setMessage(success); if (id) await openDetail(id); await load(); return true; } catch (reason) { setError(reason instanceof Error ? reason.message : "Operação não concluída."); return false; } finally { setBusy(false); } }
  async function saveProfile(payload: Record<string, unknown>) { const editing = profile || undefined, ok = await command(payload, editing ? "Fornecedor atualizado." : "Fornecedor cadastrado.", editing?.id); if (ok) setProfile(undefined); return ok; }
  async function batch(action: string, value: string) { if (!selected.length || !value) return; const payload = action === "tag" ? { action: "batch.tag", supplierIds: selected, tagId: Number(value) } : action === "homologation" ? { action: "batch.homologation", supplierIds: selected, homologationStatus: value } : { action: "batch.status", supplierIds: selected, status: value }; if (await command(payload, `${selected.length} fornecedor(es) atualizado(s).`)) setSelected([]); }
  function exportCsv() { const exportParams = new URLSearchParams(params); exportParams.delete("page"); exportParams.delete("limit"); exportParams.set("format", "csv"); const link = document.createElement("a"); link.href = `/api/erp/suppliers?${exportParams}`; link.download = "fornecedores.csv"; link.click(); }
  if (loading && !data.generatedAt) return <Loading />;
  if (fatal) return <Fatal message={fatal} retry={() => { setLoading(true); void load(); }} />;
  const maxGrowth = Math.max(1, ...data.analytics.growth.map((item) => item.count)), maxTop = Math.max(1, ...data.analytics.topSuppliers.map((item) => item.spend));
  return <div className={`${styles.workspace} ${styles.workspaceAccent}`}>
    <section className={styles.hero}><div><span>SUPRIMENTOS · SUPPLIER 360</span><h1>Central de fornecedores</h1><p>Homologue parceiros, acompanhe risco e desempenho, governe documentos e conecte compras, catálogo, notas fiscais e contas a pagar.</p></div><section><small>Base homologada</small><strong>{data.summary.total ? Math.round(data.summary.approved / data.summary.total * 100) : 0}%</strong><p>{data.summary.approved} fornecedor(es) aptos para comprar</p><time>Atualizado {data.generatedAt ? relativeTime(data.generatedAt) : "agora"}</time></section><nav><Link href="/erp/compras-cotacoes"><ErpIcon name="purchases" />Compras e cotações</Link><Link href="/erp/entrada-nfe"><ErpIcon name="invoices" />Entrada de NF-e</Link><Link href="/erp/contas-pagar-receber"><ErpIcon name="finance" />Contas a pagar</Link></nav></section>
    {message && <div className={styles.notice} role="status"><span>{message}</span><button aria-label="Fechar aviso" onClick={() => setMessage("")}>×</button></div>}{error && <div className={styles.error} role="alert"><span>{error}</span><button aria-label="Fechar erro" onClick={() => setError("")}>×</button></div>}
    <section className={styles.metrics}><Metric label="Fornecedores" value={String(data.summary.total)} detail={`${data.summary.active} ativos · ${data.summary.new30d} novos`} tone="blue" /><Metric label="Homologados" value={String(data.summary.approved)} detail="Aptos para novas compras" tone="green" /><Metric label="Volume comprado" value={money.format(data.summary.spend)} detail="Pedidos não cancelados" tone="violet" /><Metric label="Contas em aberto" value={money.format(data.summary.openPayables)} detail={`${money.format(data.summary.overduePayables)} vencidos`} tone={data.summary.overduePayables ? "red" : "green"} /><Metric label="Performance média" value={`${data.summary.averagePerformance}%`} detail="Qualidade, prazo e compliance" tone="amber" /><Metric label="Itens vinculados" value={String(data.summary.linkedProducts)} detail="Catálogo de fornecimento" tone="blue" /></section>
    <section className={styles.control}><div className={styles.tabs} role="tablist" aria-label="Visões da central"><button role="tab" aria-selected={view === "overview"} onClick={() => setView("overview")}>Visão executiva</button><button role="tab" aria-selected={view === "portfolio"} onClick={() => setView("portfolio")}>Carteira <b>{data.pagination.total}</b></button><button role="tab" aria-selected={view === "quality"} onClick={() => setView("quality")}>Homologação <b>{data.analytics.quality.pendingDocuments}</b></button></div><div className={styles.topActions}><button onClick={exportCsv}>Exportar CSV</button>{data.capabilities.canWrite && <><button onClick={() => setImportOpen(true)}>Importar</button><button className={styles.primary} onClick={() => setProfile(null)}>+ Novo fornecedor</button></>}</div></section>
    {view === "overview" && <section className={styles.overview}><section className={styles.panel}><header><div><span>EVOLUÇÃO DA BASE</span><h2>Novos fornecedores por mês</h2></div><b>{data.summary.new30d} nos últimos 30 dias</b></header><div className={styles.growth}>{data.analytics.growth.map((item) => <div key={item.month}><i style={{ height: `${Math.max(5, item.count / maxGrowth * 100)}%` }}><b>{item.count}</b></i><span>{item.month}</span></div>)}</div></section><section className={styles.panel}><header><div><span>MIX DE FORNECIMENTO</span><h2>Distribuição por categoria</h2></div></header><Breakdown rows={data.analytics.categories.map((item) => ({ name: labels[item.category] || item.category, count: item._count._all }))} total={data.summary.total} /></section><section className={styles.panel}><header><div><span>CONCENTRAÇÃO</span><h2>Maiores fornecedores</h2></div><Link className={styles.mutedLink} href="/erp/compras-cotacoes">Abrir compras</Link></header><div className={styles.topList}>{data.analytics.topSuppliers.map((item) => <article key={item.id}><strong>{item.name}</strong><span><i style={{ width: `${item.spend / maxTop * 100}%` }} /></span><b>{money.format(item.spend)}</b></article>)}{!data.analytics.topSuppliers.length && <Empty title="Sem compras consolidadas" text="Os maiores parceiros aparecerão após os primeiros pedidos." />}</div></section><section className={styles.panel}><header><div><span>HOMOLOGAÇÃO</span><h2>Situação da base</h2></div></header><Breakdown rows={data.analytics.homologations.map((item) => ({ name: labels[item.homologationStatus] || item.homologationStatus, count: item._count._all }))} total={data.summary.total} /></section><section className={`${styles.panel} ${styles.attention}`}><header><div><span>FILA DE ATENÇÃO</span><h2>Prioridades da equipe de suprimentos</h2></div><button onClick={() => setView("portfolio")}>Abrir carteira</button></header><div>{[{ key: "documents", label: "Documentos críticos", value: data.analytics.quality.pendingDocuments }, { key: "pending", label: "Homologação pendente", value: data.analytics.homologations.filter((item) => item.homologationStatus !== "approved").reduce((sum, item) => sum + item._count._all, 0) }, { key: "incomplete", label: "Cadastros incompletos", value: Math.max(data.analytics.quality.missingEmail, data.analytics.quality.missingPhone, data.analytics.quality.missingAddress) }, { key: "tasks", label: "Tarefas abertas", value: data.items.reduce((sum, item) => sum + item.metrics.pendingTasks, 0) }].map((item) => <button key={item.key} onClick={() => { setFilters((current) => ({ ...current, attention: item.key })); setPage(1); setView("portfolio"); }}><span><b>{item.label}</b><small>Clique para filtrar e tratar</small></span><b>{item.value}</b></button>)}</div></section></section>}
    {view === "portfolio" && <Portfolio data={data} filters={filters} setFilters={(value) => { setFilters((current) => ({ ...current, ...value })); setPage(1); }} page={page} setPage={setPage} selected={selected} setSelected={setSelected} openDetail={openDetail} edit={(item) => setProfile(item)} batch={batch} busy={busy} />}
    {view === "quality" && <Quality data={data} filter={(attention) => { setFilters((current) => ({ ...current, attention })); setPage(1); setView("portfolio"); }} openDetail={openDetail} />}
    {(detailLoading || detail) && <SupplierDetail supplier={detail} loading={detailLoading} meta={detailMeta} canWrite={data.capabilities.canWrite} busy={busy} close={() => { setDetail(null); setDetailLoading(false); }} edit={() => detail && setProfile(detail)} command={(payload, success) => detail ? command(payload, success, detail.id) : Promise.resolve(false)} />}
    {profile !== undefined && <ProfileModal supplier={profile || undefined} busy={busy} close={() => setProfile(undefined)} save={saveProfile} />}
    {importOpen && <ImportModal busy={busy} close={() => setImportOpen(false)} submit={async (rows, mode) => { const ok = await command({ action: "import", rows, mode }, "Importação concluída."); if (ok) setImportOpen(false); return ok; }} />}
  </div>;
}

function Portfolio({ data, filters, setFilters, page, setPage, selected, setSelected, openDetail, edit, batch, busy }: { data: Data; filters: Record<string, string>; setFilters: (value: typeof filters) => void; page: number; setPage: (value: number) => void; selected: number[]; setSelected: (value: number[]) => void; openDetail: (id: number) => void; edit: (item: Supplier) => void; batch: (action: string, value: string) => void; busy: boolean }) { const all = data.items.length > 0 && data.items.every((item) => selected.includes(item.id)); return <div className={styles.quality}><form className={styles.filters} onSubmit={(event) => event.preventDefault()}><label>Busca<input value={filters.search} onChange={(event) => setFilters({ ...filters, search: event.target.value })} placeholder="Nome, documento, contato ou comprador…" /></label><Select label="Status" value={filters.status} change={(status) => setFilters({ ...filters, status })} options={[["", "Todos"], ["active", "Ativos"], ["inactive", "Inativos"]]} /><Select label="Categoria" value={filters.category} change={(category) => setFilters({ ...filters, category })} options={[["", "Todas"], ["goods", "Mercadorias"], ["services", "Serviços"], ["logistics", "Logística"], ["technology", "Tecnologia"], ["utilities", "Utilidades"], ["other", "Outros"]]} /><Select label="Homologação" value={filters.homologation} change={(homologation) => setFilters({ ...filters, homologation })} options={[["", "Todas"], ["approved", "Homologados"], ["pending", "Pendentes"], ["conditional", "Condicionais"], ["expired", "Vencidos"], ["rejected", "Reprovados"]]} /><Select label="Risco" value={filters.risk} change={(risk) => setFilters({ ...filters, risk })} options={[["", "Todos"], ["low", "Baixo"], ["medium", "Médio"], ["high", "Alto"], ["blocked", "Bloqueado"], ["unrated", "Não avaliado"]]} /><Select label="Ordenar" value={filters.sort} change={(sort) => setFilters({ ...filters, sort })} options={[["name", "Nome"], ["recent", "Atualização"], ["spend", "Volume comprado"], ["performance", "Performance"]]} /><div><button type="button" onClick={() => setFilters({ search: "", status: "", category: "", risk: "", homologation: "", attention: "", sort: "name" })}>Limpar</button></div></form>{selected.length > 0 && <div className={styles.batch}><strong>{selected.length} selecionado(s)</strong><select aria-label="Alterar status em lote" defaultValue="" onChange={(event) => { void batch("status", event.target.value); event.target.value = ""; }} disabled={busy}><option value="">Status…</option><option value="active">Ativar</option><option value="inactive">Inativar</option></select><select aria-label="Homologar em lote" defaultValue="" onChange={(event) => { void batch("homologation", event.target.value); event.target.value = ""; }} disabled={busy}><option value="">Homologação…</option><option value="approved">Homologar</option><option value="conditional">Condicionar</option><option value="pending">Revisar</option></select><select aria-label="Aplicar etiqueta em lote" defaultValue="" onChange={(event) => { void batch("tag", event.target.value); event.target.value = ""; }} disabled={busy}><option value="">Etiqueta…</option>{data.tags.map((tag) => <option key={tag.id} value={tag.id}>{tag.name}</option>)}</select><button onClick={() => setSelected([])}>Cancelar</button></div>}<section className={styles.tablePanel}><header><div><span>CARTEIRA DE SUPRIMENTOS</span><h2>Fornecedores encontrados</h2></div><small>{data.pagination.total} registro(s)</small></header><div className={styles.tableScroll}><table><thead><tr><th><input type="checkbox" aria-label="Selecionar página" checked={all} onChange={() => setSelected(all ? [] : data.items.map((item) => item.id))} /></th><th>Fornecedor</th><th>Homologação</th><th>Compras</th><th>Financeiro</th><th>Performance</th><th>Última compra</th><th><span className={styles.srOnly}>Ações</span></th></tr></thead><tbody>{data.items.map((item) => <tr key={item.id}><td><input type="checkbox" aria-label={`Selecionar ${item.tradeName || item.name}`} checked={selected.includes(item.id)} onChange={() => setSelected(selected.includes(item.id) ? selected.filter((id) => id !== item.id) : [...selected, item.id])} /></td><td><button className={styles.supplierName} onClick={() => void openDetail(item.id)}><i>{initials(item.tradeName || item.name)}</i><span><strong>{item.tradeName || item.name}</strong><small>{formatDocument(item.document)} · {labels[item.category]}</small></span></button><div className={styles.tags}>{item.tagLinks.slice(0, 3).map(({ tag }) => <span key={tag.id} style={{ borderColor: tag.color, color: tag.color }}>{tag.name}</span>)}</div></td><td><span className={`${styles.badge} ${styles[item.homologationStatus] || ""}`}>{labels[item.homologationStatus]}</span><small>{labels[item.riskRating]} risco</small></td><td><strong>{money.format(item.metrics.spend)}</strong><small>{item.metrics.orders} pedido(s) · {item._count.products} itens</small></td><td><strong>{money.format(item.metrics.openPayables)}</strong><small>{item.metrics.overduePayables ? `${money.format(item.metrics.overduePayables)} vencidos` : "Sem vencidos"}</small></td><td><Score value={item.metrics.performanceScore || item.health.score} /><small>{item.metrics.performanceScore ? "Avaliação" : "Saúde cadastral"}</small></td><td>{item.metrics.lastPurchaseAt ? date.format(new Date(item.metrics.lastPurchaseAt)) : "—"}<small>{item.metrics.expiringDocuments ? `${item.metrics.expiringDocuments} doc. crítico(s)` : labels[item.status]}</small></td><td><details className={styles.actions}><summary aria-label={`Ações de ${item.tradeName || item.name}`}>•••</summary><div><button onClick={() => void openDetail(item.id)}>Abrir visão 360</button>{data.capabilities.canWrite && <button onClick={() => edit(item)}>Editar cadastro</button>}<Link href="/erp/compras-cotacoes">Nova compra</Link></div></details></td></tr>)}</tbody></table>{!data.items.length && <Empty title="Nenhum fornecedor encontrado" text="Ajuste os filtros ou cadastre um novo parceiro de fornecimento." />}</div><Pagination page={page} pages={data.pagination.pages} setPage={setPage} /></section></div>; }

function Quality({ data, filter, openDetail }: { data: Data; filter: (value: string) => void; openDetail: (id: number) => void }) { const quality = data.analytics.quality; return <div className={styles.quality}><section className={styles.panel}><header><div><span>QUALIDADE DA BASE</span><h2>Pendências que afetam compras seguras</h2></div></header><div className={styles.qualityGrid}>{[{ label: "Documentos críticos", value: quality.pendingDocuments, key: "documents" }, { label: "Sem e-mail", value: quality.missingEmail, key: "incomplete" }, { label: "Sem telefone", value: quality.missingPhone, key: "incomplete" }, { label: "Sem endereço", value: quality.missingAddress, key: "incomplete" }].map((item) => <button key={item.label} onClick={() => filter(item.key)}><b>{item.value}</b><span>{item.label}</span><small>Revisar registros →</small></button>)}</div></section><section className={styles.panel}><header><div><span>POSSÍVEIS DUPLICIDADES</span><h2>Contatos compartilhados</h2></div><b>{quality.duplicateGroups} grupo(s)</b></header><div className={styles.duplicateList}>{data.duplicates.map((group) => <article key={`${group.field}-${group.value}`}><span><strong>{group.field}</strong><small>{group.value}</small></span><div>{group.items.map((item) => <button key={item.id} onClick={() => void openDetail(item.id)}>{item.name}</button>)}</div></article>)}{!data.duplicates.length && <Empty title="Nenhuma duplicidade provável" text="Não encontramos e-mails ou telefones repetidos na base." />}</div></section></div>; }

function SupplierDetail({ supplier, loading, meta, canWrite, busy, close, edit, command }: { supplier: DetailSupplier | null; loading: boolean; meta: { productCatalog: Array<{ id: number; name: string; sku: string; unit: string; cost: number }>; audit: Array<{ id: string; action: string; createdAt: string }> }; canWrite: boolean; busy: boolean; close: () => void; edit: () => void; command: (payload: Record<string, unknown>, success: string) => Promise<boolean> }) { const [tab, setTab] = useState<"summary" | "operations" | "catalog" | "relationship" | "compliance">("summary"); return <ErpModal close={close} className={styles.detailLayer} label="Visão 360 do fornecedor"><section className={styles.detailDialog}>{loading || !supplier ? <div className={styles.detailLoading}>Carregando visão 360…</div> : <><header><div className={styles.identity}><i>{initials(supplier.tradeName || supplier.name)}</i><span><small>FORNECEDOR 360 · {labels[supplier.category]}</small><h2>{supplier.tradeName || supplier.name}</h2><p>{formatDocument(supplier.document)} · {labels[supplier.homologationStatus]} · Performance {supplier.metrics.performanceScore}%</p></span></div><div className={styles.detailActions}>{canWrite && <button onClick={edit}>Editar perfil</button>}<Link href="/erp/compras-cotacoes">Compras</Link></div><button className={styles.close} onClick={close} aria-label="Fechar">×</button></header><nav className={styles.detailTabs} role="tablist" aria-label="Detalhes do fornecedor">{[["summary", "Resumo"], ["operations", "Operações"], ["catalog", `Catálogo (${supplier.products.length})`], ["relationship", "Relacionamento"], ["compliance", `Homologação (${supplier.complianceDocuments.length})`]].map(([key, label]) => <button key={key} role="tab" aria-selected={tab === key} onClick={() => setTab(key as typeof tab)}>{label}</button>)}</nav><div className={styles.detailBody}>{tab === "summary" && <Summary supplier={supplier} />}{tab === "operations" && <Operations supplier={supplier} />}{tab === "catalog" && <Catalog supplier={supplier} catalog={meta.productCatalog} canWrite={canWrite} busy={busy} command={command} />}{tab === "relationship" && <Relationship supplier={supplier} canWrite={canWrite} busy={busy} command={command} />}{tab === "compliance" && <Compliance supplier={supplier} audit={meta.audit} canWrite={canWrite} busy={busy} command={command} />}</div></>}</section></ErpModal>; }

function Summary({ supplier }: { supplier: DetailSupplier }) { const evaluation = supplier.evaluations[0]; return <div className={styles.detailGrid}><section className={styles.detailMetrics}><div><small>Compras</small><strong>{money.format(supplier.metrics.spend)}</strong></div><div><small>Contas em aberto</small><strong>{money.format(supplier.metrics.openPayables)}</strong></div><div><small>Performance</small><strong>{supplier.metrics.performanceScore}%</strong></div><div><small>Saúde do cadastro</small><strong>{supplier.health.score}%</strong></div></section><section className={styles.infoBlock}><header><h3>Perfil comercial e fiscal</h3><span>{labels[supplier.homologationStatus]}</span></header><dl><div><dt>Categoria</dt><dd>{labels[supplier.category]}</dd></div><div><dt>Comprador responsável</dt><dd>{supplier.buyer || "Não definido"}</dd></div><div><dt>Regime tributário</dt><dd>{labels[supplier.taxRegime]}</dd></div><div><dt>IE / IM</dt><dd>{supplier.stateRegistration || "—"} / {supplier.municipalRegistration || "—"}</dd></div><div><dt>Condição</dt><dd>{supplier.paymentTerms || `${supplier.paymentTermsDays} dias`}</dd></div><div><dt>Lead time padrão</dt><dd>{supplier.deliveryLeadTimeDays} dias</dd></div><div><dt>Pedido mínimo</dt><dd>{money.format(supplier.minimumOrder)}</dd></div><div><dt>Origem</dt><dd>{labels[supplier.origin]}</dd></div></dl></section><section className={styles.infoBlock}><header><h3>Contato e localização</h3></header><dl><div><dt>E-mail</dt><dd>{supplier.email || "Não informado"}</dd></div><div><dt>Telefone</dt><dd>{formatPhone(supplier.phone)}</dd></div><div><dt>Site</dt><dd>{supplier.website || "Não informado"}</dd></div><div><dt>Localidade</dt><dd>{supplier.addresses[0] ? [supplier.addresses[0].city, supplier.addresses[0].state].filter(Boolean).join("/") || "Incompleto" : "Não informada"}</dd></div></dl></section><section className={styles.infoBlock}><header><h3>Última avaliação</h3><span>{evaluation ? date.format(new Date(evaluation.evaluatedAt)) : "Pendente"}</span></header>{evaluation ? <div className={styles.performanceGrid}><article><small>Qualidade</small><strong>{evaluation.qualityScore}</strong></article><article><small>Entrega</small><strong>{evaluation.deliveryScore}</strong></article><article><small>Comercial</small><strong>{evaluation.commercialScore}</strong></article><article><small>Compliance</small><strong>{evaluation.complianceScore}</strong></article></div> : <Empty title="Sem avaliação" text="Registre uma avaliação periódica para medir o desempenho do parceiro." />}</section><section className={styles.infoBlock}><header><h3>Pontos de atenção</h3><span>{supplier.health.issues.length}</span></header><p>{supplier.health.issues.length ? supplier.health.issues.join(" · ") : "Cadastro completo e sem alertas operacionais relevantes."}</p></section><section className={styles.infoBlock}><header><h3>Observações internas</h3></header><p>{supplier.notes || "Nenhuma observação registrada."}</p></section></div>; }

function Operations({ supplier }: { supplier: DetailSupplier }) { const timeline = [...supplier.purchaseOrders.map((item) => ({ id: `o-${item.id}`, title: item.number, detail: `${labels[item.status] || item.status} · ${item._count.items} itens`, amount: item.total, at: item.createdAt })), ...supplier.purchaseInvoices.map((item) => ({ id: `i-${item.id}`, title: `NF-e ${item.number}/${item.series}`, detail: labels[item.status] || item.status, amount: item.total, at: item.issueDate }))].sort((a, b) => Date.parse(b.at) - Date.parse(a.at)).slice(0, 30); return <div className={styles.detailGrid}><section className={`${styles.business} ${styles.wide}`}><header><h3>Linha do tempo de compras e documentos</h3></header><div className={styles.businessCards}><div><b>{supplier.purchaseOrders.length}</b><span>Pedidos recentes</span></div><div><b>{supplier.purchaseInvoices.length}</b><span>Notas fiscais</span></div><div><b>{supplier.quotationOffers.length}</b><span>Cotações respondidas</span></div><div><b>{money.format(supplier.metrics.invoiceValue)}</b><span>Valor em notas</span></div><div><b>{money.format(supplier.metrics.overduePayables)}</b><span>Pagamentos vencidos</span></div></div><div className={styles.timeline}>{timeline.map((item) => <article key={item.id}><i /><span><strong>{item.title}</strong><small>{item.detail}</small></span><em>{date.format(new Date(item.at))}</em><b>{money.format(item.amount)}</b></article>)}{!timeline.length && <Empty title="Sem operações" text="Pedidos e notas fiscais serão consolidados aqui." />}</div></section><section className={styles.infoBlock}><header><h3>Contas a pagar</h3><span>{supplier.financialTitles.length}</span></header><div className={styles.documentList}>{supplier.financialTitles.slice(0, 12).map((item) => <article key={item.id}><span><strong>{item.description}</strong><small>Vence {date.format(new Date(item.dueAt))} · {labels[item.status] || item.status}</small></span><b>{money.format(item.amount - item.paidAmount)}</b></article>)}</div></section><section className={styles.infoBlock}><header><h3>Cotações</h3><span>{supplier.quotationOffers.length}</span></header><div className={styles.documentList}>{supplier.quotationOffers.slice(0, 12).map((item) => <article key={item.id}><span><strong>{item.quotation.number} · {item.quotation.title}</strong><small>{item.leadTimeDays} dias · {item.paymentTerms || "Condição não informada"}</small></span><b>{money.format(item.total)}</b></article>)}</div></section></div>; }

function Catalog({ supplier, catalog, canWrite, busy, command }: { supplier: DetailSupplier; catalog: Array<{ id: number; name: string; sku: string; unit: string; cost: number }>; canWrite: boolean; busy: boolean; command: (payload: Record<string, unknown>, success: string) => Promise<boolean> }) { return <div className={styles.relationship}>{canWrite && <form className={styles.addressForm} onSubmit={(event) => { event.preventDefault(); void command({ action: "product.upsert", ...Object.fromEntries(new FormData(event.currentTarget)) }, "Produto vinculado ao fornecedor."); event.currentTarget.reset(); }}><header><h3>Vincular produto</h3><p>Registre código, custo, lote e prazo específicos deste parceiro.</p></header><div><label className={styles.wide}>Produto<select name="productId" required defaultValue=""><option value="" disabled>Selecione…</option>{catalog.filter((product) => !supplier.products.some((item) => item.productId === product.id)).map((product) => <option key={product.id} value={product.id}>{product.sku} · {product.name}</option>)}</select></label><label>Código no fornecedor<input name="supplierCode" /></label><label>Último custo<input name="lastCost" type="number" min="0" step="0.01" /></label><label>Lead time (dias)<input name="leadTimeDays" type="number" min="0" max="365" /></label><label>Lote mínimo<input name="productMinimumOrder" type="number" min="0" step="0.001" /></label><label className={styles.check}><input name="preferred" type="checkbox" />Fornecedor preferencial</label></div><button disabled={busy}>Vincular produto</button></form>}<section className={`${styles.infoBlock} ${styles.wide}`}><header><h3>Catálogo fornecido</h3><span>{supplier.products.length}</span></header><div className={styles.productList}>{supplier.products.map((item) => <article key={item.productId}><span><strong>{item.product.sku} · {item.product.name}{item.preferred ? " · Preferencial" : ""}</strong><small>{item.supplierCode || "Sem código externo"} · {item.lastCost == null ? "Custo não informado" : money.format(item.lastCost)} · {item.leadTimeDays ?? supplier.deliveryLeadTimeDays} dias</small></span>{canWrite && <button disabled={busy} onClick={() => void command({ action: "product.remove", productId: item.productId }, "Produto desvinculado.")}>Remover</button>}</article>)}{!supplier.products.length && <Empty title="Nenhum produto vinculado" text="Vincule o catálogo negociado com este fornecedor." />}</div></section></div>; }

function Relationship({ supplier, canWrite, busy, command }: { supplier: DetailSupplier; canWrite: boolean; busy: boolean; command: (payload: Record<string, unknown>, success: string) => Promise<boolean> }) { return <div className={styles.relationship}>{canWrite && <div className={styles.actionForms}><form onSubmit={(event) => { event.preventDefault(); void command({ action: "interaction.create", ...Object.fromEntries(new FormData(event.currentTarget)) }, "Interação registrada."); event.currentTarget.reset(); }}><header><h3>Registrar interação</h3><p>Acompanhe negociações e próximos passos.</p></header><div><label>Tipo<select name="type" defaultValue="negotiation"><option value="negotiation">Negociação</option><option value="call">Ligação</option><option value="email">E-mail</option><option value="meeting">Reunião</option><option value="task">Tarefa</option><option value="note">Nota</option></select></label><label>Prazo<input name="dueAt" type="datetime-local" /></label><label className={styles.wide}>Assunto<input name="subject" required /></label><label className={styles.wide}>Detalhes<textarea name="notes" /></label></div><button disabled={busy}>Registrar</button></form><form onSubmit={(event) => { event.preventDefault(); void command({ action: "contact.create", ...Object.fromEntries(new FormData(event.currentTarget)) }, "Contato adicionado."); event.currentTarget.reset(); }}><header><h3>Novo contato</h3><p>Cadastre comercial, financeiro e pós-venda.</p></header><div><label>Nome<input name="name" required /></label><label>Cargo / área<input name="role" /></label><label>E-mail<input name="email" type="email" /></label><label>Telefone<input name="phone" /></label><label className={styles.check}><input name="primary" type="checkbox" />Contato principal</label></div><button disabled={busy}>Adicionar contato</button></form></div>}<section className={styles.infoBlock}><header><h3>Contatos</h3><span>{supplier.contacts.length}</span></header><div className={styles.contactList}>{supplier.contacts.map((item) => <article key={item.id}><i>{initials(item.name)}</i><span><strong>{item.name}{item.primary ? " · Principal" : ""}</strong><small>{item.role || "Contato"} · {item.email || formatPhone(item.phone)}</small></span>{canWrite && <button disabled={busy} onClick={() => void command({ action: "contact.archive", contactId: item.id }, "Contato arquivado.")}>Arquivar</button>}</article>)}</div></section><section className={styles.infoBlock}><header><h3>Interações e tarefas</h3><span>{supplier.interactions.length}</span></header><div className={styles.interactionList}>{supplier.interactions.map((item) => <article key={item.id}><span className={styles.interactionIcon}>{item.completedAt ? "✓" : labels[item.type]?.slice(0, 1)}</span><span><strong>{item.subject}</strong><small>{labels[item.type]} · {item.createdBy} · {dateTime.format(new Date(item.createdAt))}{item.dueAt ? ` · Prazo ${dateTime.format(new Date(item.dueAt))}` : ""}</small>{item.notes && <p>{item.notes}</p>}</span>{canWrite && item.type === "task" && <button disabled={busy} onClick={() => void command({ action: "interaction.complete", interactionId: item.id, completed: !item.completedAt }, item.completedAt ? "Tarefa reaberta." : "Tarefa concluída.")}>{item.completedAt ? "Reabrir" : "Concluir"}</button>}</article>)}</div></section><section className={`${styles.infoBlock} ${styles.wide}`}><header><h3>Etiquetas</h3></header><div className={styles.tagEditor}>{supplier.tagLinks.map(({ tag }) => <span key={tag.id} style={{ borderColor: tag.color, color: tag.color }}>{tag.name}{canWrite && <button aria-label={`Remover ${tag.name}`} onClick={() => void command({ action: "tag.remove", tagId: tag.id }, "Etiqueta removida.")}>×</button>}</span>)}{canWrite && <form onSubmit={(event) => { event.preventDefault(); void command({ action: "tag.add", ...Object.fromEntries(new FormData(event.currentTarget)) }, "Etiqueta aplicada."); event.currentTarget.reset(); }}><input name="name" placeholder="Nova etiqueta" required /><input name="color" type="color" defaultValue="#218e88" aria-label="Cor" /><button disabled={busy}>Adicionar</button></form>}</div></section></div>; }

function Compliance({ supplier, audit, canWrite, busy, command }: { supplier: DetailSupplier; audit: Array<{ id: string; action: string; createdAt: string }>; canWrite: boolean; busy: boolean; command: (payload: Record<string, unknown>, success: string) => Promise<boolean> }) { return <div className={styles.relationship}>{canWrite && <div className={styles.actionForms}><form onSubmit={(event) => { event.preventDefault(); void command({ action: "document.create", ...Object.fromEntries(new FormData(event.currentTarget)) }, "Documento registrado."); event.currentTarget.reset(); }}><header><h3>Registrar documento</h3><p>Controle validade e evidências da homologação.</p></header><div><label>Tipo<select name="documentType"><option value="tax">Fiscal</option><option value="license">Licença</option><option value="certificate">Certificado</option><option value="insurance">Seguro</option><option value="contract">Contrato</option><option value="bank">Bancário</option><option value="other">Outro</option></select></label><label>Status<select name="status"><option value="valid">Válido</option><option value="pending">Pendente</option><option value="expired">Vencido</option><option value="rejected">Rejeitado</option></select></label><label className={styles.wide}>Nome<input name="name" required /></label><label>Número<input name="number" /></label><label>Emissão<input name="issuedAt" type="date" /></label><label>Validade<input name="expiresAt" type="date" /></label><label className={styles.wide}>Referência do arquivo<input name="fileReference" placeholder="URL, protocolo ou caminho no GED" /></label></div><button disabled={busy}>Registrar documento</button></form><form onSubmit={(event) => { event.preventDefault(); void command({ action: "evaluation.create", ...Object.fromEntries(new FormData(event.currentTarget)) }, "Avaliação registrada."); event.currentTarget.reset(); }}><header><h3>Avaliar fornecedor</h3><p>Notas de 0 a 100, preservadas no histórico.</p></header><div className={styles.scoreInputs}><label>Qualidade<input name="qualityScore" type="number" min="0" max="100" required /></label><label>Entrega<input name="deliveryScore" type="number" min="0" max="100" required /></label><label>Comercial<input name="commercialScore" type="number" min="0" max="100" required /></label><label>Conformidade<input name="complianceScore" type="number" min="0" max="100" required /></label><label className={styles.wide}>Observações<textarea name="notes" /></label></div><button disabled={busy}>Salvar avaliação</button></form></div>}<section className={styles.infoBlock}><header><h3>Documentos de homologação</h3><span>{supplier.complianceDocuments.length}</span></header><div className={styles.documentList}>{supplier.complianceDocuments.map((item) => { const expired = item.expiresAt && Date.parse(item.expiresAt) < Date.now(); return <article key={item.id}><span><strong>{item.name}</strong><small>{labels[item.type]} · {item.number || "Sem número"}{item.expiresAt ? ` · Validade ${date.format(new Date(item.expiresAt))}` : ""}</small></span><em className={`${styles.badge} ${expired ? styles.docExpired : item.status !== "valid" ? styles.docAlert : styles.valid}`}>{expired ? "Vencido" : labels[item.status]}</em></article>; })}{!supplier.complianceDocuments.length && <Empty title="Sem documentos" text="Registre certidões, licenças, seguros e contratos exigidos na homologação." />}</div></section><section className={styles.infoBlock}><header><h3>Histórico de avaliações</h3><span>{supplier.evaluations.length}</span></header><div className={styles.documentList}>{supplier.evaluations.map((item) => <article key={item.id}><span><strong>Performance {Math.round((item.qualityScore * .3) + (item.deliveryScore * .3) + (item.commercialScore * .15) + (item.complianceScore * .25))}%</strong><small>{item.evaluatedBy} · {date.format(new Date(item.evaluatedAt))}</small></span><b>{item.qualityScore}/{item.deliveryScore}/{item.commercialScore}/{item.complianceScore}</b></article>)}</div></section><section className={`${styles.infoBlock} ${styles.wide}`}><header><h3>Rastreabilidade</h3><span>{audit.length}</span></header><div className={styles.auditList}>{audit.map((item) => <article key={item.id}><i /><span><strong>{auditLabel(item.action)}</strong><small>{dateTime.format(new Date(item.createdAt))}</small></span></article>)}</div></section></div>; }

function ProfileModal({ supplier, busy, close, save }: { supplier?: Supplier; busy: boolean; close: () => void; save: (payload: Record<string, unknown>) => Promise<boolean> }) { const address = supplier?.addresses[0]; return <ErpModal close={close} className={styles.profileLayer} label={supplier ? "Editar fornecedor" : "Novo fornecedor"}><form className={styles.profileDialog} onSubmit={async (event) => { event.preventDefault(); await save({ ...Object.fromEntries(new FormData(event.currentTarget)), ...(supplier ? { version: supplier.version } : {}) }); }}><header><div><span>CADASTRO DE FORNECEDOR</span><h2>{supplier ? "Editar perfil" : "Novo fornecedor"}</h2><p>Dados fiscais, comerciais, logísticos e de homologação.</p></div><button type="button" onClick={close} aria-label="Fechar">×</button></header><div className={styles.profileBody}><fieldset><legend>Identificação</legend><SupplierCnpjLookup /><label className={styles.wide}>Nome / razão social<input name="name" defaultValue={supplier?.name || ""} required /></label><label>Nome fantasia<input name="tradeName" defaultValue={supplier?.tradeName || ""} /></label><label>CPF ou CNPJ<input name="document" defaultValue={formatDocument(supplier?.document)} inputMode="numeric" required /></label><label>E-mail<input name="email" type="email" defaultValue={supplier?.email || ""} /></label><label>Telefone<input name="phone" defaultValue={formatPhone(supplier?.phone)} /></label><label>Site<input name="website" type="url" defaultValue={supplier?.website || ""} placeholder="https://" /></label></fieldset><fieldset><legend>Suprimentos e risco</legend><label>Categoria<select name="category" defaultValue={supplier?.category || "goods"}>{[["goods", "Mercadorias"], ["services", "Serviços"], ["logistics", "Logística"], ["technology", "Tecnologia"], ["utilities", "Utilidades"], ["other", "Outros"]].map(([value, text]) => <option value={value} key={value}>{text}</option>)}</select></label><label>Origem<select name="origin" defaultValue={supplier?.origin || "manual"}>{[["manual", "Manual"], ["purchase", "Compras"], ["invoice", "Nota fiscal"], ["import", "Importação"], ["referral", "Indicação"]].map(([value, text]) => <option value={value} key={value}>{text}</option>)}</select></label><label>Comprador responsável<input name="buyer" defaultValue={supplier?.buyer || ""} /></label><label>Risco<select name="riskRating" defaultValue={supplier?.riskRating || "unrated"}><option value="unrated">Não avaliado</option><option value="low">Baixo</option><option value="medium">Médio</option><option value="high">Alto</option><option value="blocked">Bloqueado</option></select></label><label>Homologação<select name="homologationStatus" defaultValue={supplier?.homologationStatus || "pending"}><option value="pending">Pendente</option><option value="approved">Homologado</option><option value="conditional">Condicional</option><option value="rejected">Reprovado</option><option value="expired">Vencido</option></select></label><label>Lead time padrão (dias)<input name="deliveryLeadTimeDays" type="number" min="0" max="365" defaultValue={supplier?.deliveryLeadTimeDays || 0} /></label><label>Pedido mínimo<input name="minimumOrder" type="number" min="0" step="0.01" defaultValue={supplier?.minimumOrder || 0} /></label></fieldset><fieldset><legend>Fiscal e financeiro</legend><label>Regime tributário<select name="taxRegime" defaultValue={supplier?.taxRegime || "not_informed"}><option value="not_informed">Não informado</option><option value="mei">MEI</option><option value="simples">Simples Nacional</option><option value="presumed">Lucro presumido</option><option value="actual">Lucro real</option><option value="individual">Pessoa física</option></select></label><label>Inscrição estadual<input name="stateRegistration" defaultValue={supplier?.stateRegistration || ""} /></label><label>Inscrição municipal<input name="municipalRegistration" defaultValue={supplier?.municipalRegistration || ""} /></label><label>Condição de pagamento<input name="paymentTerms" defaultValue={supplier?.paymentTerms || ""} placeholder="Ex.: 28/42 dias" /></label><label>Prazo médio (dias)<input name="paymentTermsDays" type="number" min="0" max="365" defaultValue={supplier?.paymentTermsDays || 0} /></label></fieldset><fieldset><legend>Endereço principal</legend><label>CEP<input name="zip" defaultValue={String(address?.zip || "")} inputMode="numeric" /></label><label className={styles.wide}>Logradouro<input name="street" defaultValue={String(address?.street || "")} /></label><label>Número<input name="number" defaultValue={String(address?.number || "")} /></label><label>Complemento<input name="complement" defaultValue={String(address?.complement || "")} /></label><label>Bairro<input name="district" defaultValue={String(address?.district || "")} /></label><label>Cidade<input name="city" defaultValue={String(address?.city || "")} /></label><label>UF<input name="state" maxLength={2} defaultValue={String(address?.state || "")} /></label></fieldset><fieldset><legend>Uso interno</legend><label className={styles.wide}>Observações<textarea name="notes" defaultValue={supplier?.notes || ""} /></label></fieldset></div><footer><span>Alterações ficam registradas na trilha de auditoria.</span><div><button type="button" onClick={close}>Cancelar</button><button className={styles.primary} disabled={busy}>{busy ? "Salvando…" : "Salvar fornecedor"}</button></div></footer></form></ErpModal>; }

function ImportModal({ busy, close, submit }: { busy: boolean; close: () => void; submit: (rows: Array<Record<string, string>>, mode: string) => Promise<boolean> }) { const [rows, setRows] = useState<Array<{ row: number; value: Record<string, string> }>>([]), [error, setError] = useState(""), [fileName, setFileName] = useState(""), [mode, setMode] = useState("skip"); async function receive(file?: File) { if (!file) return; setError(""); try { const parsed = parseSupplierCsv(await file.text()); setRows(parsed); setFileName(file.name); } catch (reason) { setRows([]); setFileName(""); setError(reason instanceof Error ? reason.message : "Não foi possível ler o CSV."); } } function template() { const content = "nome;nome_fantasia;cpf_cnpj;email;telefone;categoria;origem;comprador;risco;homologacao;regime_tributario;condicao_pagamento;prazo_pagamento_dias;lead_time_dias;pedido_minimo;cidade;uf\r\nFornecedor Exemplo;;11222333000181;compras@example.com;11999990000;goods;manual;Equipe de compras;low;approved;simples;28 dias;28;5;500;São Paulo;SP", url = URL.createObjectURL(new Blob([`\uFEFF${content}`], { type: "text/csv;charset=utf-8" })), link = document.createElement("a"); link.href = url; link.download = "modelo-fornecedores.csv"; link.click(); URL.revokeObjectURL(url); } return <ErpModal close={close} className={styles.profileLayer} label="Importar fornecedores"><form className={`${styles.profileDialog} ${styles.importDialog}`} onSubmit={async (event) => { event.preventDefault(); if (!rows.length) return setError("Selecione e valide um arquivo CSV."); await submit(rows.map((item) => item.value), mode); }}><header><div><span>IMPORTAÇÃO CONTROLADA</span><h2>Importar fornecedores em CSV</h2><p>Pré-visualize até 500 registros e defina como tratar documentos existentes.</p></div><button type="button" onClick={close} aria-label="Fechar">×</button></header><div className={styles.importBody}><button className={styles.dropzone} type="button" onDragOver={(event) => event.preventDefault()} onDrop={(event) => { event.preventDefault(); void receive(event.dataTransfer.files[0]); }} onClick={(event) => (event.currentTarget.nextElementSibling as HTMLInputElement | null)?.click()}><ErpIcon name="suppliers" /><strong>{fileName || "Arraste o CSV aqui ou clique para escolher"}</strong><small>CSV com vírgula ou ponto e vírgula · máximo 2 MB e 500 linhas</small></button><input className={styles.fileInput} type="file" accept=".csv,text/csv" onChange={(event) => void receive(event.target.files?.[0])} /><div className={styles.importOptions}><label>Quando o CPF/CNPJ já existir<select value={mode} onChange={(event) => setMode(event.target.value)}><option value="skip">Ignorar e preservar cadastro</option><option value="update">Atualizar pelo CSV</option></select></label><button type="button" onClick={template}>Baixar arquivo modelo</button></div>{error && <div className={styles.inlineError} role="alert">{error}</div>}{rows.length > 0 && <section className={styles.preview}><header><h3>Prévia do arquivo</h3><b>{rows.length} fornecedor(es)</b></header><div><table><thead><tr><th>Linha</th><th>Nome</th><th>CPF/CNPJ</th><th>Categoria</th><th>Homologação</th><th>Cidade/UF</th></tr></thead><tbody>{rows.slice(0, 8).map((item) => <tr key={item.row}><td>{item.row}</td><td>{item.value.name || "—"}</td><td>{formatDocument(item.value.document)}</td><td>{labels[item.value.category] || item.value.category || "Mercadorias"}</td><td>{labels[item.value.homologationStatus] || item.value.homologationStatus || "Pendente"}</td><td>{[item.value.city, item.value.state].filter(Boolean).join("/") || "—"}</td></tr>)}</tbody></table></div></section>}</div><footer><span>Nenhum dado é gravado antes da validação integral.</span><div><button type="button" onClick={close}>Cancelar</button><button className={styles.primary} disabled={busy || !rows.length}>{busy ? "Importando…" : `Importar ${rows.length || ""} fornecedor(es)`}</button></div></footer></form></ErpModal>; }

function Metric({ label, value, detail, tone }: { label: string; value: string; detail: string; tone: string }) { return <article className={`${styles.metric} ${styles[tone]}`}><small>{label}</small><strong>{value}</strong><span>{detail}</span></article>; }
function Score({ value }: { value: number }) { return <span className={`${styles.score} ${value >= 80 ? styles.scoreGood : value >= 55 ? styles.scoreWarn : styles.scoreBad}`}><i style={{ "--score": `${value * 3.6}deg` } as React.CSSProperties} /><b>{value}</b></span>; }
function Select({ label, value, change, options }: { label: string; value: string; change: (value: string) => void; options: string[][] }) { return <label><span>{label}</span><select value={value} onChange={(event) => change(event.target.value)}>{options.map(([id, text]) => <option key={id} value={id}>{text}</option>)}</select></label>; }
function Breakdown({ rows, total }: { rows: Array<{ name: string; count: number }>; total: number }) { return <div className={styles.breakdown}>{rows.map((row) => <div key={row.name}><span><strong>{row.name}</strong><small>{row.count} fornecedor(es)</small></span><i><em style={{ width: `${total ? row.count / total * 100 : 0}%` }} /></i><strong>{total ? Math.round(row.count / total * 100) : 0}%</strong></div>)}</div>; }
function Pagination({ page, pages, setPage }: { page: number; pages: number; setPage: (page: number) => void }) { if (pages <= 1) return null; return <footer className={styles.pagination}><button disabled={page <= 1} onClick={() => setPage(page - 1)}>← Anterior</button><span>Página <b>{page}</b> de {pages}</span><button disabled={page >= pages} onClick={() => setPage(page + 1)}>Próxima →</button></footer>; }
function Empty({ title, text }: { title: string; text: string }) { return <div className={styles.empty}><b>◇</b><strong>{title}</strong><p>{text}</p></div>; }
function Loading() { return <div className={styles.loading}><div /><div /><div /><section /></div>; }
function Fatal({ message, retry }: { message: string; retry: () => void }) { return <section className={styles.fatal}><ErpIcon name="suppliers" /><h2>Central de fornecedores indisponível</h2><p>{message}</p><button onClick={retry}>Tentar novamente</button></section>; }
function initials(value: string) { return value.trim().split(/\s+/).slice(0, 2).map((part) => part[0]?.toUpperCase()).join("") || "FO"; }
function formatDocument(value?: string | null) { const digits = String(value || "").replace(/\D/g, ""); if (digits.length === 11) return digits.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, "$1.$2.$3-$4"); if (digits.length === 14) return digits.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/, "$1.$2.$3/$4-$5"); return value || "Não informado"; }
function formatPhone(value?: string | null) { const digits = String(value || "").replace(/\D/g, ""); if (digits.length === 11) return digits.replace(/(\d{2})(\d{5})(\d{4})/, "($1) $2-$3"); if (digits.length === 10) return digits.replace(/(\d{2})(\d{4})(\d{4})/, "($1) $2-$3"); return value || "Sem telefone"; }
function relativeTime(value: string) { const minutes = Math.max(0, Math.round((Date.now() - Date.parse(value)) / 60_000)); return minutes < 1 ? "agora" : minutes < 60 ? `há ${minutes} min` : `às ${tenantDateTimeFormatter({ timeStyle: "short" }).format(new Date(value))}`; }
function auditLabel(action: string) { return ({ "supplier.created": "Fornecedor cadastrado", "supplier.updated": "Cadastro atualizado", "supplier.status_changed": "Status alterado", "supplier.homologation_changed": "Homologação alterada", "supplier.contact_created": "Contato adicionado", "supplier.contact_archived": "Contato arquivado", "supplier.interaction_created": "Interação registrada", "supplier.interaction_completed": "Tarefa concluída", "supplier.document_created": "Documento registrado", "supplier.document_updated": "Documento atualizado", "supplier.evaluation_created": "Avaliação registrada", "supplier.product_saved": "Produto vinculado", "supplier.product_removed": "Produto removido", "supplier.tag_added": "Etiqueta aplicada", "supplier.tag_removed": "Etiqueta removida" } as Record<string, string>)[action] || action.replaceAll("_", " "); }
